x_938076_backup_0_backup_scripts.script:
gs.info('********************Trade Level*****************************');

var excelRowArray = [];

//getting the attachment
var getAttachment = new GlideRecord('sys_attachment');
getAttachment.addEncodedQuery('table_sys_id=' + '78271e1347c12200e0ef563dbb9a7109');
getAttachment.query();
if (getAttachment.next()) {
    var attachmentRec = getAttachment.getValue('sys_id');
}
//getting attachment

var attachment = new GlideSysAttachment(); //method to get the contents of the attachment
var attachmentDetails = attachment.getContentStream(attachmentRec); //getting content of the EXcel

var parser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
parser.setSource(attachmentDetails); //setting the source to parse the content from the stream

var getSheet = parser.getSheetNames(); //getting the sheet name to fetch details
parser.setSheetName(getSheet); //setting the sheet to parse

if (parser.parse()) { //converting into readable format using parse

    while (parser.next()) { //iterating over each row
        var getRows = parser.getRow(); //reading row by row
        var rowObj = JSON.stringify(getRows); //holds the rows of Excel as comma sepearated
        excelRowArray.push(rowObj + '');

    }
}

gs.info(excelRowArray.toString());



gs.info('********************Trade Level*****************************');



var bulkexcelRowArray = [];
//getting the attachment
var bulkgetAttachment = new GlideRecord('sys_attachment');
bulkgetAttachment.addEncodedQuery('table_sys_id=' + 'a83820b58f723300e7e16c7827bdeed2');
bulkgetAttachment.query();
if (bulkgetAttachment.next()) {
    var bulkattachmentRec = bulkgetAttachment.getValue('sys_id');
}
//getting attachment

var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
var bulkattachmentDetails = bulkattachment.getContentStream(bulkattachmentRec); //getting content of the EXcel

var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
bulkparser.setSheetName(bulkgetSheet); //setting the sheet to parse

if (bulkparser.parse()) { //converting into readable format using parse

    while (bulkparser.next()) { //iterating over each row
        var bulkgetRows = bulkparser.getRow(); //reading row by row
		bulkgetRows.business = 'DCC HK'; //add the owning business for each array item which will be used for error validation
        var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
        bulkexcelRowArray.push(bulkrowObj + '');

    }
}

gs.info(bulkexcelRowArray.toString());
